import {
  AI_ATTACHMENT_LIMITS as limits,
  AI_IMAGE_TYPES,
  isAiTextFile,
} from '../backend/domain/ai-attachments.js';
import type { AiAttachmentInput } from '../backend/domain/ai-attachments.js';
// Draft identity is local to this page; persisted IDs are generated by the server.
let attachmentSequence = 0;
export interface DraftAiAttachment extends AiAttachmentInput {
  id: string;
  size: number;
}
export async function readAiFiles(
  files: readonly File[],
  existingCount = 0,
  existingBytes = 0,
): Promise<DraftAiAttachment[]> {
  if (existingCount + files.length > limits.count) throw Error('最多添加 4 个附件');
  let total = existingBytes;
  const result: DraftAiAttachment[] = [];
  for (const file of files) {
    const image = (AI_IMAGE_TYPES as readonly string[]).includes(file.type);
    const archive = /\.zip$/i.test(file.name);
    if (!image && !archive && !isAiTextFile(file.name))
      throw Error('支持 ZIP 技能包、文本、代码、日志和 PNG、JPEG、WebP 图片');
    if (!file.size || file.size > (archive ? limits.archive : image ? limits.image : limits.text))
      throw Error(
        archive
          ? 'ZIP 技能包不能超过 4 MiB'
          : image
            ? '单张图片不能超过 2 MiB'
            : '文本附件不能为空或超过 256 KiB',
      );
    total += file.size;
    if (total > limits.total) throw Error('附件总大小不能超过 4 MiB');
    const buffer = new Uint8Array(await file.arrayBuffer());
    let data: string;
    if (image || archive) {
      let binary = '';
      for (let i = 0; i < buffer.length; i += 16384)
        binary += String.fromCharCode(...buffer.subarray(i, i + 16384));
      data = btoa(binary);
    } else {
      try {
        data = new TextDecoder('utf-8', { fatal: true }).decode(buffer);
      } catch {
        throw Error('文本附件需使用 UTF-8 编码');
      }
      if (data.includes('\0')) throw Error('请选择纯文本文件');
    }
    result.push({
      id: 'attachment-' + ++attachmentSequence,
      name: file.name,
      kind: archive ? 'archive' : image ? 'image' : 'text',
      mimeType: archive ? 'application/zip' : image ? file.type : 'text/plain',
      data,
      size: image || archive ? buffer.length : new TextEncoder().encode(data).length,
    });
  }
  return result;
}
export function attachmentSize(size: number): string {
  return size < 1024
    ? `${size} B`
    : size < 1048576
      ? `${(size / 1024).toFixed(1)} KiB`
      : `${(size / 1048576).toFixed(1)} MiB`;
}
